// Workflow D - validate a staff status-update request (Header Auth already enforced by the Webhook node).
const b = ($input.first().json || {}).body || {};
const STATUS = ['PREPARING', 'READY', 'OUT_FOR_DELIVERY', 'COMPLETED', 'CANCELLED'];
const PAY = ['PAID', 'FAILED', 'REFUNDED', 'PAYMENT_PENDING'];
const ref = String(b.order_ref || '').trim().toUpperCase();
const status = String(b.status || '').trim().toUpperCase();
const pay = String(b.payment_status || '').trim().toUpperCase();
const actor = String(b.actor || 'staff').replace(/[^\w .@-]/g, '').slice(0, 60) || 'staff';
const note = String(b.note || '').replace(/[\u0000-\u001F\u007F]/g, ' ').slice(0, 200);
let error = null;
if (!/^BK-\d{6}-\d{5}-[A-Z0-9]{3}$/.test(ref)) error = 'invalid order_ref';
else if ((status && pay) || (!status && !pay)) error = 'send exactly one of status or payment_status';
else if (status && !STATUS.includes(status)) error = 'invalid status';
else if (pay && !PAY.includes(pay)) error = 'invalid payment_status';
return [{ json: { valid: !error, error, order_ref: ref, status, payment_status: pay, actor, note } }];

// Workflow D - turn claimed outbox rows into Cloud API request bodies. The recipient always comes from the database row.
const S = ($('Load Settings').first().json || {}).settings || {};
// ---- shared helpers (inlined by tools/build_workflows.py at //@@LIB@@) ----
const CUR = String(S.currency_symbol || S.currency_code || '');
function fmt(minor) {
  const n = Number(minor) || 0, a = Math.abs(n), whole = Math.floor(a / 100), frac = a % 100;
  return (n < 0 ? '-' : '') + CUR + String(whole).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + (frac ? '.' + String(frac).padStart(2, '0') : '');
}
function clip(s, n) { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; }
function plain(s, n) { return clip(String(s == null ? '' : s).replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim(), n); }
const STATUS_LABEL = { CONFIRMED: 'Confirmed', PREPARING: 'Being prepared', READY: 'Ready', OUT_FOR_DELIVERY: 'Out for delivery', COMPLETED: 'Completed', CANCELLED: 'Cancelled' };
const PAY_LABEL = { PAYMENT_PENDING: 'payment pending', PAID: 'paid', FAILED: 'payment failed', REFUNDED: 'refunded' };
function optsText(o) {
  if (!o || typeof o !== 'object') return '';
  const parts = [o.flavor, o.egg, o.frosting].filter(Boolean);
  let t = parts.join(', ');
  if (o.message) t += (t ? '; ' : '') + 'message: “' + plain(o.message, 60) + '”';
  return t ? ' [' + t + ']' : '';
}
function leadText(m) {
  m = Number(m) || 0;
  if (m < 120) return m + ' minutes';
  if (m < 2880) return Math.ceil(m / 60) + ' hours';
  return Math.ceil(m / 1440) + ' days';
}
function hoursText() {
  const H = S.opening_hours || {}, names = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'], groups = [];
  for (let i = 1; i <= 7; i++) {
    const h = H[String(i)], key = Array.isArray(h) ? h.join('-') : 'closed', last = groups[groups.length - 1];
    if (last && last.key === key) last.to = names[i - 1]; else groups.push({ key, from: names[i - 1], to: names[i - 1] });
  }
  return groups.map(g => (g.from === g.to ? g.from : g.from + '–' + g.to) + ' ' + g.key.replace('-', '–')).join(', ');
}
function lineText(l) {
  return l.line_no + '. ' + l.name + ' (' + l.variant + ') × ' + l.quantity + ' — ' + fmt(l.line_total_minor) + optsText(l.options);
}
function totalsText(c) {
  let t = 'Subtotal: ' + fmt(c.subtotal_minor);
  if (Number(c.delivery_fee_minor) > 0) t += '\nDelivery: ' + fmt(c.delivery_fee_minor);
  if (Number(c.tax_minor) > 0) t += '\nTax: ' + fmt(c.tax_minor);
  return t + '\n*Total: ' + fmt(c.total_minor) + '*';
}
function whenText(c) {
  const m = c.fulfillment_method === 'DELIVERY' ? 'Delivery' : 'Pickup';
  return m + ' — ' + (c.requested_local || 'time not set');
}

const ver = String($env.WHATSAPP_API_VERSION || ''), pnid = String($env.META_PHONE_NUMBER_ID || '');
const configOk = /^v\d{1,2}\.\d{1,2}$/.test(ver) && /^\d{5,25}$/.test(pnid);
const url = configOk ? 'https://graph.facebook.com/' + ver + '/' + pnid + '/messages' : '';
const one = (s, n) => plain(s, n).replace(/\s{2,}/g, ' ');
function orderItems(o) {
  return (o.items || []).map(i => '• ' + i.quantity + ' × ' + one(i.name, 60) + ' (' + one(i.variant, 20) + ')' + optsText(i.options)).join('\n');
}
function orderHead(o) { return (o.fulfillment_method === 'DELIVERY' ? 'Delivery' : 'Pickup') + ': ' + o.requested_local; }
function build(row) {
  const o = row.order || {};
  switch (row.kind) {
    case 'ORDER_CONFIRMED_CUSTOMER':
      return '✅ *Order confirmed!*\nReference: *' + o.order_ref + '*\n\n' + orderItems(o) + '\n\n' + orderHead(o) + (o.fulfillment_method === 'DELIVERY' ? '\nAddress: ' + one(o.delivery_address, 200) : '') +
        '\nTotal: *' + fmt(o.total_minor) + '*\nPayment: ' + (PAY_LABEL[o.payment_status] || o.payment_status) + '. ' + (S.payment_instructions || '') + '\n\nSay “status” to check your order, or “cancel my order” if you change your mind (subject to our cancellation rules).';
    case 'ORDER_NEW_BAKERY':
      return '🧾 *New order ' + o.order_ref + '*\nCustomer: ' + one(o.contact_name, 60) + ' (+' + o.contact_wa_id + ')\n\n' + orderItems(o) + '\n\n' + orderHead(o) + (o.fulfillment_method === 'DELIVERY' ? '\nAddress: ' + one(o.delivery_address, 200) : '') +
        '\nTotal: ' + fmt(o.total_minor) + ' · ' + (PAY_LABEL[o.payment_status] || o.payment_status);
    case 'ORDER_CANCELLED_BAKERY':
      return '❌ *Order cancelled by customer:* ' + o.order_ref + '\n' + one(o.contact_name, 60) + ' (+' + o.contact_wa_id + ')\n' + orderHead(o) + '\nTotal: ' + fmt(o.total_minor);
    case 'ORDER_STATUS_CUSTOMER': {
      const st = (row.payload || {}).status, note = (row.payload || {}).note;
      const msg = { PREPARING: 'We have started preparing it 🧁', READY: 'It is ready for ' + (o.fulfillment_method === 'DELIVERY' ? 'dispatch' : 'pickup') + ' 🎉', OUT_FOR_DELIVERY: 'It is out for delivery 🚚', COMPLETED: 'It is complete. Thank you! 💛', CANCELLED: 'It has been cancelled.' }[st] || 'Its status is now ' + (STATUS_LABEL[st] || st) + '.';
      return 'Update on order *' + o.order_ref + '*: ' + msg + (note ? '\n' + one(note, 200) : '');
    }
  }
  return '';
}
function tpl(t, row, text) {
  if (!t || !t.name || t.name === 'REPLACE_WITH_TEMPLATE_NAME') return null;
  const o = row.order || {};
  const vals = { order_ref: o.order_ref || '', summary: one((o.items || []).map(i => i.quantity + ' x ' + i.name).join(', '), 400), total: o.total_minor !== undefined ? fmt(o.total_minor) : '' };
  const params = (Array.isArray(t.params) ? t.params : []).map(k => ({ type: 'text', text: one(vals[k] || '-', 500) }));
  const template = { name: String(t.name), language: { code: String(t.language || 'en_US') } };
  if (params.length) template.components = [{ type: 'body', parameters: params }];
  return { type: 'template', template };
}
const out = [];
for (const it of $input.all()) {
  const row = it.json.item;
  const base = { id: row.id, send: false, outcome: null, code: null, text: null, provider_id: null, url, body: null };
  if (!configOk) { out.push({ json: Object.assign(base, { outcome: 'PERMANENT', code: 'CONFIG', text: 'WHATSAPP_API_VERSION or META_PHONE_NUMBER_ID missing/invalid' }) }); continue; }
  let msg = null;
  if (row.kind === 'REPLY') {
    const p = row.payload || {};
    if (row.window_open && p.message) msg = (row.last_error_code === 'INTERACTIVE_REJECTED' && p.fallback_text) ? { type: 'text', text: { body: clip(p.fallback_text, 4000), preview_url: false } } : p.message;
  } else {
    const text = build(row);
    if (!text) { out.push({ json: Object.assign(base, { outcome: 'PERMANENT', code: 'NO_TEMPLATE', text: 'unknown notification kind or missing order' }) }); continue; }
    if (row.window_open) msg = { type: 'text', text: { body: clip(text, 4000), preview_url: false } };
    else msg = tpl(row.recipient_type === 'BAKERY' ? S.bakery_notify_template : S.customer_status_template, row, text);
  }
  if (!msg) { out.push({ json: Object.assign(base, { outcome: 'BLOCKED_WINDOW', code: '131047', text: 'outside 24h window and no approved template configured' }) }); continue; }
  out.push({ json: Object.assign(base, { send: true, body: Object.assign({ messaging_product: 'whatsapp', recipient_type: 'individual', to: row.recipient_wa_id }, msg) }) });
}
return out;

// Workflow D - classify the WhatsApp Cloud API response. Retry only what is safe to retry.
const sent = $('Can Send?').all(0);          // items that went into the HTTP node, same order
const mask = (s) => String(s == null ? '' : s).replace(/\d{7,}/g, '[n]').replace(/Bearer\s+\S+/gi, 'Bearer [x]').slice(0, 250);
const out = [];
$input.all().forEach((it, i) => {
  const src = sent[(it.pairedItem && it.pairedItem.item !== undefined) ? it.pairedItem.item : i];
  const id = src && src.json ? src.json.id : null;
  const j = it.json || {};
  const status = Number(j.statusCode);
  const body = j.body && typeof j.body === 'object' ? j.body : {};
  const err = body.error || {};
  const code = String(err.code !== undefined ? err.code : '');
  let outcome, ec = code || String(status || ''), text = mask(err.message || (j.error && (j.error.message || j.error)) || '');
  let pid = null;
  if (!status) { outcome = 'RETRY'; ec = 'NETWORK'; text = mask(j.error && (j.error.message || j.error.description) || 'no response (timeout/network)'); }
  else if (status >= 200 && status < 300) {
    pid = body.messages && body.messages[0] && body.messages[0].id;
    if (pid) outcome = 'SENT'; else { outcome = 'PERMANENT'; ec = 'BAD_PROVIDER_RESPONSE'; text = 'success status without message id'; }
  }
  else if (status === 401 || code === '190') { outcome = 'AUTH'; ec = 'AUTH'; }
  else if (code === '131047' || code === '131051') { outcome = 'BLOCKED_WINDOW'; }
  else if (status === 429 || status === 408 || status >= 500 || ['130429', '131056', '80007', '131000', '133016'].includes(code)) { outcome = 'RETRY'; }
  else if (status === 400 && (code === '100' || code === '131009') && src && src.json.body && src.json.body.type === 'interactive') { outcome = 'RETRY'; ec = 'INTERACTIVE_REJECTED'; }
  else { outcome = 'PERMANENT'; }
  out.push({ json: { id, outcome, code: ec, text, provider_id: pid || null } });
});
return out;
